// ─── Resolve industry to image key ──────────────────────────

function resolveIndustryKey(businessType: string): string {
  const bt = businessType.toLowerCase().replace(/[^a-z0-9 ]/g, "");
  
  // Direct matches
  if (bt.includes("real estate") || bt.includes("property") || bt.includes("housing") || bt.includes("apartment") || bt.includes("rental")) return "real-estate";
  if (bt.includes("restaurant") || bt.includes("food") || bt.includes("cafe") || bt.includes("bakery") || bt.includes("catering") || bt.includes("kitchen") || bt.includes("cook")) return "restaurant";
  if (bt.includes("tech") || bt.includes("software") || bt.includes("saas") || bt.includes("app") || bt.includes("digital") || bt.includes("computer") || bt.includes("electronic")) return "technology";
  if (bt.includes("fitness") || bt.includes("gym") || bt.includes("sport") || bt.includes("yoga") || bt.includes("wellness") || bt.includes("health")) return "fitness";
  if (bt.includes("beauty") || bt.includes("cosmetic") || bt.includes("skincare") || bt.includes("makeup") || bt.includes("salon") || bt.includes("spa")) return "beauty";
  if (bt.includes("fashion") || bt.includes("cloth") || bt.includes("shoe") || bt.includes("apparel") || bt.includes("wear") || bt.includes("boutique")) return "fashion";
  
  return "default";
}

function getIndustryImages(businessType: string) {
  const key = resolveIndustryKey(businessType);
  return INDUSTRY_IMAGES[key] || INDUSTRY_IMAGES["default"];
}

