// ─── Build Smart Blocks ─────────────────────────────────────

export interface SmartBlockInput {
  storeName: string;
  storeSlug: string;
  businessType: string;
  description?: string;
  aiContent?: Record<string, unknown>; // AI-generated content
}

export function buildSmartAiBlocks(input: SmartBlockInput): TemplateBlock[] {
  const { storeName, storeSlug, businessType, aiContent } = input;
  const images = getIndustryImages(businessType);
  const blocks = JSON.parse(JSON.stringify(AI_TEMPLATE_PRESET)) as TemplateBlock[];
  const ai = aiContent || {};

  for (const block of blocks) {
    const props = (block.props ||= {});
    switch (block.type) {
      case "aiAnnouncementBar": {
        const msgs = ai.announcement as string[] | undefined;
        props.messages = msgs && msgs.length > 0
          ? msgs
          : [
              `Welcome to ${storeName}`,
              `Trusted ${businessType} services`,
              "Quality you can count on",
              "Contact us today",
            ];
        break;
      }

      case "aiHeroVideo": {
        props.backgroundImage = images.hero;
        props.backgroundVideo = "";
        const heroButtons = ai.heroButtons as Array<{ text: string; link: string }> | undefined;
        props.buttons = heroButtons
          ? heroButtons.map((b) => ({ text: b.text, link: `/store/${storeSlug}${b.link}`, style: "primary" }))
          : [
              { text: "Browse", link: `/store/${storeSlug}/shop`, style: "primary" },
              { text: "About Us", link: `/store/${storeSlug}/about`, style: "primary" },
            ];
        break;
      }

      case "aiCategoryRow": {
        const cats = ai.categories as Array<{ title: string; buttonLabels: string[] }> | undefined;
        const cards = (cats || [
          { title: "Featured", buttonLabels: ["View All"] },
          { title: "Popular", buttonLabels: ["Browse"] },
          { title: "New", buttonLabels: ["Explore"] },
          { title: "Trending", buttonLabels: ["See More"] },
        ]).slice(0, 4);

        props.cards = cards.map((c, i) => ({
          title: c.title,
          image: images.categories[i % images.categories.length],
          overlayOpacity: 15,
          buttons: (c.buttonLabels || ["Browse"]).map((label) => ({
            text: label,
            link: `/store/${storeSlug}/shop`,
          })),
        }));
        break;
      }

      case "aiLargeProductCarousel": {
        const featured = ai.featuredProducts as Array<{
          title: string; description: string; price: string; compareAtPrice?: string;
        }> | undefined;
        const tabLabel = (ai.featuredTabLabel as string) || "Featured";

        const products = (featured || [
          { title: "Featured Item 1", description: "Premium quality", price: "$99", compareAtPrice: "$150" },
          { title: "Featured Item 2", description: "Best seller", price: "$79", compareAtPrice: "$120" },
          { title: "Featured Item 3", description: "New arrival", price: "$59", compareAtPrice: "$90" },
          { title: "Featured Item 4", description: "Limited edition", price: "$129", compareAtPrice: "$200" },
          { title: "Featured Item 5", description: "Customer favorite", price: "$69", compareAtPrice: "$100" },
        ]).slice(0, 5);

        props.tabs = [{
          label: tabLabel,
          products: products.map((p, i) => ({
            title: p.title,
            description: p.description,
            price: p.price,
            compareAtPrice: p.compareAtPrice || undefined,
            image: images.products[i % images.products.length],
            link: `/store/${storeSlug}/shop`,
            isUnisex: true,
          })),
        }];
        break;
      }

      case "aiPromoTiles": {
        const promos = ai.promoTiles as Array<{ title: string }> | undefined;
        const promoTitles = promos || [
          { title: "New Arrivals" },
          { title: "Most Popular" },
          { title: "Special Offers" },
        ];

        props.tiles = promoTitles.slice(0, 3).map((p, i) => ({
          title: p.title,
          image: images.promos[i % images.promos.length],
          buttons: [
            { text: "Explore", link: `/store/${storeSlug}/shop` },
            { text: "Learn More", link: `/store/${storeSlug}/about` },
          ],
        }));
        break;
      }

      case "aiProductCarousel": {
        const cards = ai.productCards as Array<{
          name: string; colorway: string; price: string; compareAtPrice?: string; badge?: string | null;
        }> | undefined;
        const tabLabel = (ai.tabLabel as string) || "Popular";

        const productCards = (cards || [
          { name: "Item 1", colorway: "Standard", price: "$45", compareAtPrice: "$90", badge: "50% OFF" },
          { name: "Item 2", colorway: "Premium", price: "$55", compareAtPrice: "$110", badge: null },
          { name: "Item 3", colorway: "Classic", price: "$37", compareAtPrice: "$75", badge: "NEW" },
          { name: "Item 4", colorway: "Deluxe", price: "$65", badge: null },
          { name: "Item 5", colorway: "Standard", price: "$55", compareAtPrice: "$110", badge: null },
          { name: "Item 6", colorway: "Premium", price: "$70", compareAtPrice: "$140", badge: null },
          { name: "Item 7", colorway: "Limited", price: "$55", badge: "NEW" },
          { name: "Item 8", colorway: "Classic", price: "$62", compareAtPrice: "$125", badge: "POPULAR" },
        ]).slice(0, 8);

        props.tabs = [{
          label: tabLabel,
          products: productCards.map((p, i) => ({
            name: p.name,
            colorway: p.colorway,
            price: p.price,
            compareAtPrice: p.compareAtPrice || undefined,
            image: images.products[i % images.products.length],
            link: `/store/${storeSlug}/shop`,
            badge: p.badge || undefined,
            swatches: [{ color: "#555", label: p.colorway }],
          })),
        }];
        break;
      }

      case "aiValueProps": {
        const vps = ai.valueProps as Array<{ title: string; description: string }> | undefined;
        props.props = vps || [
          { title: "Quality First", description: `We deliver the best in ${businessType}. Every product and service meets our high standards.` },
          { title: "Trusted by Thousands", description: "Join our growing community of satisfied customers who keep coming back." },
          { title: "Expert Support", description: "Our team is here to help you every step of the way. Reach out anytime." },
        ];
        break;
      }

      case "aiFooter": {
        props.copyrightText = `© ${new Date().getFullYear()} ${storeName}. All rights reserved.`;
        const footerCols = ai.footerColumns as Array<{
          title: string; links: Array<{ text: string; link: string }>;
        }> | undefined;

        if (footerCols) {
          props.columns = footerCols.map((col) => ({
            title: col.title,
            links: col.links.map((l) => ({
              text: l.text,
              link: typeof l.link === "string" && l.link.startsWith("/store") ? l.link : `/store/${storeSlug}${String(l.link || "")}`,
            })),
          }));
        } else {
          props.columns = [
            { title: "Help", links: [
              { text: "Contact Us", link: `/store/${storeSlug}/contact` },
              { text: "FAQ", link: `/store/${storeSlug}/faq` },
            ]},
            { title: "Browse", links: [
              { text: "All Products", link: `/store/${storeSlug}/shop` },
              { text: "About Us", link: `/store/${storeSlug}/about` },
            ]},
            { title: "Legal", links: [
              { text: "Policies", link: `/store/${storeSlug}/policies` },
            ]},
          ];
        }
        break;
      }
    }
  }

  return blocks;
}
